/*
 * WHAT IS THIS FILE?
 *
 * Any file called "service-worker" is automatically bundled and registered with Qwik Router, as long as you add `<RegisterServiceWorker />` in your `root.tsx`.
 *
 * Here you register the events that your service worker will handle.
 *
 * MDN has documentation at https://developer.mozilla.org/en-US/docs/Web/API/Service_Worker_API
 */
// ^ Generated by `qwik add service-worker` (the component is `<ServiceWorkerRegister />`, in
// `root.tsx`). Everything below is ours (QWIK-DEFAULTS.md, 2026-11-24 "offline").
//
// Offline (owner, 2026-11-24): the site runs with no internet, like an installed app, and uses
// the network again as soon as there is one. A plain worker, no Workbox (keep it basic):
//
// - INSTALL: every file of this build (`build/`, `assets/`: Qwik's chunks, CSS, fonts, the map
//   worker) plus the main pages, into `spn-build-<version>`. All chunks, not only the ones used:
//   Qwik loads an event handler's chunk on first use, so a chunk not stored is a button that does
//   nothing offline. The list and the version come from the build (`scripts/sw-manifest.ts`):
//   the router exposes no file list to a service worker in rc.5.
// - PAGES (navigations) and their data (`q-loader-*.json`, `q-route.json`, `/api/search`):
//   network first, so online is always fresh; a copy goes to `spn-pages-<version>` (same build as
//   the chunks the page asks for), capped. Offline: that copy, else `/offline/`.
// - THE VISITOR'S OWN CONTACTS (`/contacts/local/<id>/`, 2026-11-24): ONE app-shell entry for all
//   of them (`LOCAL_SHELL`), the page and its loader JSON alike, network first. The HTML holds no
//   contact (the data is in the browser's own storage), only the frame, so any id's page serves
//   every id; per-id copies would fill the cache with identical pages. The page corrects its URL
//   when the shell was another id's (`routes/contacts/local/[id]/index.tsx`).
// - LIVE NODES: the `/api/nodes` snapshot network first into the pages cache (offline: the last
//   known fleet, shown with stale nodes offline by `map-nodes-live.ts`). The live WebSocket and
//   the ingest POST are never handled here.
// - MAP TILES from OpenFreeMap: tiles, fonts and sprites cache first (their URLs are versioned),
//   style and TileJSON network first; `spn-tiles`, capped, kept across builds.
// - NEVER stored: anything not GET, `/admin` (Cloudflare Access, `private, no-store`),
//   `/cdn-cgi/` (Access, Turnstile), `?qaction=` / `?qfunc=` (actions, `server$`), responses
//   marked `no-store`, pages marked `private` (loader JSON excepted, see `storable`), redirects. Other origins (Photon, OSRM, Turnstile) are left
//   to the browser: they need the internet anyway.
// - UPDATE: a new build is a new file (the version is in it), so the browser installs it;
//   `skipWaiting` + `claim` (the generated default) make it take over at once. The previous
//   build's caches are KEPT one more build: an open tab of the old build still finds its chunks
//   (they are gone from the server after a deploy). Older ones are deleted.
export declare const self: ServiceWorkerGlobalScope;

interface BuildManifest {
  /** A hash of this build's file list (and the public files the worker stores). */
  version: string;
  /** Every `build/` and `assets/` file, relative to the site root. */
  files: string[];
}

// Replaced at build time by `scripts/sw-manifest.ts` (the build fails if it is not found).
const BUILD: BuildManifest = JSON.parse("__SPN_SW_MANIFEST__");

const BUILD_PREFIX = "spn-build-";
const PAGES_PREFIX = "spn-pages-";
const PRECACHE = BUILD_PREFIX + BUILD.version;
const PAGES = PAGES_PREFIX + BUILD.version;
const TILES = "spn-tiles";
/** Remembers which build was current, so activate knows the previous one. */
const META = "spn-meta";
const META_CURRENT = "/__spn/current-build";

const PAGES_MAX = 150;
/** The one cache key every `/contacts/local/<id>/` page (and its loader JSON) is stored under. */
const LOCAL_SHELL = "/contacts/local/shell/";
const LOCAL_PAGE = /^\/contacts\/local\/[^/]+\/(.*)$/;

/** The cache key of a request: its own, or the local contacts' shell. */
function cacheKey(request: Request): Request | string {
  const url = new URL(request.url);
  const m = LOCAL_PAGE.exec(url.pathname);
  return m && url.origin === self.location.origin
    ? LOCAL_SHELL + m[1]
    : request;
}
const TILES_MAX = 800;
const OFFLINE_URL = "/offline/";
/** Stored at install. A page that fails here is skipped; it is stored when visited instead. */
const SHELL_PAGES = [
  "/",
  // About is the Contacts app since 2026-11-24 (`/about/` is a 301: never stored).
  "/contacts/",
  "/contacts/sean-perez/",
  "/messages/",
  "/maps/",
  "/search/",
  "/profile/",
  OFFLINE_URL,
];
// Must match `PUBLIC_FILES` in `scripts/sw-manifest.ts` (the icons: `scripts/icons.ts`).
const PUBLIC_FILES = [
  "/manifest.json",
  "/favicon.ico",
  "/icons/favicon.svg",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/icon-maskable-512.png",
  "/icons/apple-touch-icon.png",
  "/icons/icon-monochrome-512.png",
  "/icons/shortcut-contacts-96.png",
  "/icons/shortcut-maps-96.png",
];
const TILE_HOST = "tiles.openfreemap.org";

/**
 * A response we may keep: complete, same-origin or CORS, not a redirect, not `no-store`, and not
 * `private` unless `allowPrivate`. Qwik Router sends EVERY loader's JSON as `no-cache, private`
 * (its default, measured on the built worker 2026-11-24), not because the data is personal: the
 * site's public loaders (posts, profile, contact setup) are the same for everyone, and the only
 * per-person routes (`/admin`) are never handled here. Without them a page opened by a client
 * navigation fails offline, so loader JSON passes `allowPrivate`.
 */
function storable(response: Response, allowPrivate = false): boolean {
  if (!response.ok || response.redirected) return false;
  if (response.type !== "basic" && response.type !== "cors") return false;
  const cacheControl = response.headers.get("Cache-Control") ?? "";
  if (/\bno-store\b/i.test(cacheControl)) return false;
  return allowPrivate || !/\bprivate\b/i.test(cacheControl);
}

/** Deletes the oldest entries (`keys()` is in insertion order, MDN) above `max`. */
async function trim(cacheName: string, max: number) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  await Promise.all(
    keys
      .slice(0, Math.max(0, keys.length - max))
      .map((key) => cache.delete(key)),
  );
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(PRECACHE);
      const files = [...PUBLIC_FILES, ...BUILD.files.map((file) => `/${file}`)];
      // In batches, and past the HTTP cache (`reload`): one failure fails the install, and the
      // browser tries again on the next visit.
      for (let i = 0; i < files.length; i += 50) {
        await cache.addAll(
          files
            .slice(i, i + 50)
            .map((url) => new Request(url, { cache: "reload" })),
        );
      }
      await Promise.all(
        SHELL_PAGES.map(async (path) => {
          try {
            const response = await fetch(path, {
              cache: "reload",
              credentials: "omit",
            });
            if (storable(response)) await cache.put(path, response);
          } catch {
            // Offline mid-install, or the page is gone: stored on its first visit instead.
          }
        }),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const meta = await caches.open(META);
      const previous = await (await meta.match(META_CURRENT))?.text();
      if (previous !== BUILD.version) {
        await meta.put(META_CURRENT, new Response(BUILD.version));
      }
      const keep = new Set([PRECACHE, PAGES, TILES, META]);
      if (previous && previous !== BUILD.version) {
        keep.add(BUILD_PREFIX + previous);
        keep.add(PAGES_PREFIX + previous);
      }
      for (const name of await caches.keys()) {
        if (name.startsWith("spn-") && !keep.has(name))
          await caches.delete(name);
      }
      await self.clients.claim();
    })(),
  );
});

/** Network first; keeps a copy in `cacheName`; offline, the newest copy we have. */
async function networkFirst(
  request: Request,
  cacheName: string,
  max: number,
  allowPrivate = false,
): Promise<Response> {
  const key = cacheKey(request);
  try {
    const response = await fetch(request);
    if (storable(response, allowPrivate)) {
      const copy = response.clone();
      void caches
        .open(cacheName)
        .then((cache) => cache.put(key, copy))
        .then(() => trim(cacheName, max));
    }
    return response;
  } catch (error) {
    const cached =
      (await caches.match(key, { cacheName })) ??
      (await caches.match(key, { cacheName: PRECACHE })) ??
      (await caches.match(key));
    if (cached) return cached;
    throw error;
  }
}

/** Cache first (the file never changes at that URL); stores what the network gives. */
async function cacheFirst(
  request: Request,
  cacheName: string,
  max?: number,
): Promise<Response> {
  // Its own cache first (the current build), then any (the previous build's chunks).
  const cached =
    (await caches.match(request, { cacheName })) ??
    (await caches.match(request));
  if (cached) return cached;
  const response = await fetch(request);
  if (storable(response)) {
    const copy = response.clone();
    void caches
      .open(cacheName)
      .then((cache) => cache.put(request, copy))
      .then(() => (max ? trim(cacheName, max) : undefined));
  }
  return response;
}

async function navigate(request: Request): Promise<Response> {
  try {
    return await networkFirst(request, PAGES, PAGES_MAX);
  } catch {
    return (
      (await caches.match(OFFLINE_URL, { cacheName: PRECACHE })) ??
      (await caches.match(OFFLINE_URL)) ??
      Response.error()
    );
  }
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);

  if (url.host === TILE_HOST) {
    const versioned =
      /\.(pbf|mvt|png|webp|jpg)$/.test(url.pathname) ||
      url.pathname.startsWith("/fonts/") ||
      url.pathname.startsWith("/sprites/");
    event.respondWith(
      versioned
        ? cacheFirst(request, TILES, TILES_MAX)
        : networkFirst(request, TILES, TILES_MAX),
    );
    return;
  }

  if (url.origin !== self.location.origin) return;
  const path = url.pathname;
  if (
    path.startsWith("/admin") ||
    path.startsWith("/cdn-cgi/") ||
    path === "/service-worker.js" ||
    url.searchParams.has("qaction") ||
    url.searchParams.has("qfunc")
  ) {
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(navigate(request));
  } else if (path.startsWith("/build/") || path.startsWith("/assets/")) {
    event.respondWith(cacheFirst(request, PRECACHE));
  } else if (
    /\/q-loader-[^/]+\.json$/.test(path) ||
    path.endsWith("/q-route.json") ||
    path === "/api/search"
  ) {
    // Loader JSON is `private` by Qwik's default only (see `storable`).
    event.respondWith(networkFirst(request, PAGES, PAGES_MAX, true));
  } else if (path === "/api/nodes") {
    // The live nodes' snapshot (2026-11-24): offline, the map shows the last known fleet.
    // Its WebSocket (`/api/nodes/live`) never reaches a service worker (the WebSocket spec opens
    // it with service-workers mode "none"), and device POSTs are not GETs.
    event.respondWith(networkFirst(request, PAGES, PAGES_MAX));
  } else if (PUBLIC_FILES.includes(path)) {
    event.respondWith(cacheFirst(request, PRECACHE));
  }
});
